"""Torch references for RMSNorm kernels."""

import torch
import torch.nn.functional as F


def rmsnorm_torch(
    x: torch.Tensor,
    weight: torch.Tensor,
    eps: float = 1.0e-6,
    *,
    out: torch.Tensor | None = None,
) -> torch.Tensor:
    if x.ndim == 0:
        raise ValueError("x must have at least one dimension")
    if weight.shape != (x.shape[-1],):
        raise ValueError(f"weight shape must be {(x.shape[-1],)}, got {tuple(weight.shape)}")
    if out is not None and out.shape != x.shape:
        raise ValueError(f"out shape must be {tuple(x.shape)}, got {tuple(out.shape)}")
    result = F.rms_norm(x.float(), weight.shape, weight, float(eps)).to(x.dtype)
    if out is not None:
        out.copy_(result)
        return out
    return result


def add_rmsnorm_torch(
    residual: torch.Tensor,
    x: torch.Tensor,
    weight: torch.Tensor,
    eps: float = 1.0e-6,
    *,
    out: torch.Tensor | None = None,
) -> torch.Tensor:
    if residual.ndim == 0:
        raise ValueError("residual must have at least one dimension")
    if residual.shape != x.shape:
        raise ValueError(
            f"x must match residual shape {tuple(residual.shape)}, got {tuple(x.shape)}"
        )
    if weight.shape != (residual.shape[-1],):
        raise ValueError(
            f"weight shape must be {(residual.shape[-1],)}, got {tuple(weight.shape)}"
        )
    if out is not None and out.shape != residual.shape:
        raise ValueError(f"out shape must be {tuple(residual.shape)}, got {tuple(out.shape)}")

    added = residual + x
    residual.copy_(added)
    result = F.rms_norm(residual.float(), weight.shape, weight, float(eps)).to(
        residual.dtype
    )
    if out is not None:
        out.copy_(result)
        return out
    return result


__all__ = ["add_rmsnorm_torch", "rmsnorm_torch"]
